import re
import sys

REVIEW_TAIL = "with Accept all and Reject all; when it ends, the cursor lands on the first one in the text."


def parse(text):
    out, ours, theirs, state = [], [], [], None
    for line in text.split("\n"):
        if line.startswith("<<<<<<< "):
            state, ours, theirs = "ours", [], []
        elif line == "=======" and state == "ours":
            state = "theirs"
        elif line.startswith(">>>>>>> ") and state == "theirs":
            out.append((ours, theirs))
            state = None
        elif state == "ours":
            ours.append(line)
        elif state == "theirs":
            theirs.append(line)
        else:
            out.append(line)
    return out


def merge_description(ours, theirs):
    if REVIEW_TAIL not in theirs:
        return None
    return ours.replace("with Accept all and Reject all.", REVIEW_TAIL)


def merge_list(ours, theirs):
    key = lambda line: re.match(r"- \[([^\]]+)\]", line).group(1)
    if not all(re.match(r"- \[", l) for l in ours + theirs):
        return None
    theirs_by_key = {key(l): l for l in theirs}
    return [theirs_by_key[key(l)] if key(l) == "AI cost log" else l for l in ours]


def resolve(ours, theirs):
    if len(ours) == 1 and len(theirs) == 1 and ours[0].startswith("A browser Markdown"):
        merged = merge_description(ours[0], theirs[0])
        return None if merged is None else [merged]
    if ours and ours[0].startswith("- ["):
        return merge_list(ours, theirs)
    if ours[-1].startswith("**Running total:**") and theirs[-1].startswith("**Running total:**"):
        rows = lambda side: [l for l in side if l.startswith("| ")]
        return rows(ours) + rows(theirs) + [""] + theirs[-1:]
    if ours[0].startswith("Notes on") and theirs[0].startswith("Notes on"):
        return ours + [""] + theirs
    return None


def main(path):
    with open(path) as f:
        parts = parse(f.read())
    lines = []
    for part in parts:
        if isinstance(part, tuple):
            merged = resolve(*part)
            if merged is None:
                print(f"unresolved hunk in {path}:\nOURS: {part[0]}\nTHEIRS: {part[1]}")
                sys.exit(1)
            lines.extend(merged)
        else:
            lines.append(part)
    with open(path, "w") as f:
        f.write("\n".join(lines))


main(sys.argv[1])

